<node TEXT="Qualitative" ID="ID_1175393974" CREATED="1714584289152" MODIFIED="1714584293213" MOVED="1714585337152">
<node TEXT="Definitions and characteristics" ID="ID_1827485422" CREATED="1714585228158" MODIFIED="1714585237444" MOVED="1714586766682">
<node TEXT="general characteristics of qualitative research: providing rich descriptions rather than numeric measurements; study individuals in their natural settings rather than controlling all possible variables; smaller number of participants and less concern about generalizability; emic perspective (categories seen through the eyes of participants and their community); cyclical and open-ended, process-oriented, categories emerge from the research itself rather than being a priori hypotheses." ID="ID_3070365" CREATED="1714584199144" MODIFIED="1714584199144" LINK="project://16AA1F3483D6GEWV5A1JJLVG6C22R89VFR4E/../../../articulos/pedagogy/Mackey2005SecondLanguageResearch.pdf">
<attribute NAME="key" VALUE="Mackey2005SecondLanguageResearch"/>
<attribute NAME="title" VALUE="Second Language Research"/>
<attribute NAME="authors" VALUE="Mackey, Alison and Gass, Susan M."/>
<pdf_annotation type="HIGHLIGHTED_TEXT" page="179" object_id="8228347369287229494" object_number="3"/>
</node>
