<attribute NAME="authors" VALUE="Mackey, Alison and Gass, Susan M."/>
<pdf_annotation type="HIGHLIGHTED_TEXT" page="196" object_id="2362839043592567569" object_number="1638"/>
</node>
<node TEXT="Researcher biases" ID="ID_1555418795" CREATED="1714585561722" MODIFIED="1714585570942">
<node TEXT="diary analysis: search for patterns to find recurring themes. Caveats: researchers must be conscious of their own beliefs regarding the focal topic; note not just how often a topic appears but which of the participants expresses it; salience must be taken into account as well as simple mentions to avoid over- or underemphasis" ID="ID_796297498" CREATED="1714584199208" MODIFIED="1714584199208" LINK="project://16AA1F3483D6GEWV5A1JJLVG6C22R89VFR4E/../../../articulos/pedagogy/Mackey2005SecondLanguageResearch.pdf">
<attribute NAME="key" VALUE="Mackey2005SecondLanguageResearch"/>
<attribute NAME="title" VALUE="Second Language Research"/>
<attribute NAME="authors" VALUE="Mackey, Alison and Gass, Susan M."/>
<pdf_annotation type="HIGHLIGHTED_TEXT" page="222" object_id="3123061426916470177" object_number="1742"/>
</node>
</node>
<node TEXT="Response to criticisms" ID="ID_820566209" CREATED="1714585481864" MODIFIED="1714585486751" MOVED="1714585594058">
<node TEXT="transferability: in a way, there is rarely any direct and absolute transferability to other contexts; the key element is to report richly on the context in which data was gathered so that readers can assess the transferability to their own situations. An important approach in this regard is *thick description*, in which multiple perspectives are used to explain the insights, and the participants&apos; interpretations are taken into account." ID="ID_1297622435" CREATED="1714584199284" MODIFIED="1714584199284" LINK="project://16AA1F3483D6GEWV5A1JJLVG6C22R89VFR4E/../../../articulos/pedagogy/Mackey2005SecondLanguageResearch.pdf">
<attribute NAME="key" VALUE="Mackey2005SecondLanguageResearch"/>
<attribute NAME="title" VALUE="Second Language Research"/>
<attribute NAME="authors" VALUE="Mackey, Alison and Gass, Susan M."/>
<pdf_annotation type="HIGHLIGHTED_TEXT" page="197" object_id="7149333315283019892" object_number="1654"/>
</node>
<node TEXT="Thematic case study is context specific and situationally bounded, demonstrating *trustworthiness* is not related to the possibility to duplicate findings, but on transparency, providing and audit trail and a chain of evidence. You can do this by foregrounding clarity, making explicit your research decisions (e.g. systematic tabulation of coded data extracts, providing explicit code and category descriptions). This transparency allows readers to draw their own conclusions about the applicability to their contexts of interest" ID="ID_1630190390" CREATED="1714584198979" MODIFIED="1714584198979" LINK="project://16AA1F3483D6GEWV5A1JJLVG6C22R89VFR4E/../../../articulos/pedagogy/Peel2020BeginnersGuideApplied.pdf" MOVED="1714586163834">
<attribute NAME="key" VALUE="Peel2020BeginnersGuideApplied"/>
<attribute NAME="title" VALUE="A Beginner&apos;s Guide to Applied Educational Research using Thematic Analysis"/>
<attribute NAME="authors" VALUE="Peel, Karen L."/>
<pdf_annotation type="HIGHLIGHTED_TEXT" page="12" object_id="6579760453548184481" object_number="200"/>
</node>
<node TEXT="Triangulation" ID="ID_709521375" CREATED="1714585861175" MODIFIED="1714587160111">
