<node TEXT="Approaches and perspectives" ID="ID_434105068" CREATED="1714586494586" MODIFIED="1714586500526">
<node TEXT="exploratory orientation in qualitative analysis (as opposed to the less common confirmatory orientation): themes, trends, keywords not established a priori but coming through the reading of the data itself; content driven; based on research questions rather than specific hypotheses, but commonly used to generate hypotheses for further study" ID="ID_1580748378" CREATED="1714584199389" MODIFIED="1714584199389" LINK="project://16AA1F3483D6GEWV5A1JJLVG6C22R89VFR4E/../../../articulos/pedagogy/Guest2012AppliedThematicAnalysis.pdf">
<attribute NAME="key" VALUE="Guest2012AppliedThematicAnalysis"/>
<attribute NAME="title" VALUE="Applied Thematic Analysis"/>
<attribute NAME="authors" VALUE="Guest, Greg and MacQueen, Kathleen and Namey, Emily"/>
<pdf_annotation type="HIGHLIGHTED_TEXT" page="7" object_id="6687222650939845859" object_number="2423"/>
</node>
<node TEXT="Exploratory analysis: classic inductive approach associated with qualitative research; emphasis on what emerges from the interaction between researcher and respondent, which drives code development and theme identification" ID="ID_1948749651" CREATED="1714584199367" MODIFIED="1714584199368" LINK="project://16AA1F3483D6GEWV5A1JJLVG6C22R89VFR4E/../../../articulos/pedagogy/Guest2012AppliedThematicAnalysis.pdf">
