<attribute NAME="authors" VALUE="Peel, Karen L."/>
<pdf_annotation type="HIGHLIGHTED_TEXT" page="10" object_id="7362640810954085479" object_number="195"/>
</node>
<node TEXT="strategies to develop an analysis of co-occurrences of themes and relationships: compare thematically related groups of codes by participant characteristics; after each step, summarize the main emerging patterns and note interesting, contradictory, or puzzling elements; remember that this is still an exploratory step. Frequency and co-occurrence tables can then be used to generate search statements (e.g. Boolean searches) to locate text for further analysis" ID="ID_1055231804" CREATED="1714584199860" MODIFIED="1714584199860" LINK="project://16AA1F3483D6GEWV5A1JJLVG6C22R89VFR4E/../../../articulos/pedagogy/Guest2012AppliedThematicAnalysis.pdf">
