<pdf_annotation type="HIGHLIGHTED_TEXT" page="171" object_id="5810745128252435578" object_number="692"/>
</node>
</node>
<node TEXT="Bounding" ID="ID_1159407783" CREATED="1714586708659" MODIFIED="1714586711415">
<node TEXT="Bounding, i.e. establishing the boundaries of a particular analysis: deciding which sources of data (groups, events, indidividuals),  conceptual domains, and specific questions should be included in the analysis. The same dataset can be bounded in different ways for different purposes (research question, audience, report format…)" ID="ID_460620892" CREATED="1714584199869" MODIFIED="1714584199869" LINK="project://16AA1F3483D6GEWV5A1JJLVG6C22R89VFR4E/../../../articulos/pedagogy/Guest2012AppliedThematicAnalysis.pdf">
