<pdf_annotation type="HIGHLIGHTED_TEXT" page="47" object_id="6461689426370468751" object_number="574"/>
</node>
<node TEXT="structural coding: data segmentation done on the basis of the structure of the collection instrument (e.g., each question and followups in a semi-structured interview is a data segment). Some codes can be based in the question topics too." ID="ID_8147210" CREATED="1714584199769" MODIFIED="1714584199769" LINK="project://16AA1F3483D6GEWV5A1JJLVG6C22R89VFR4E/../../../articulos/pedagogy/Guest2012AppliedThematicAnalysis.pdf">
