<pdf_annotation type="HIGHLIGHTED_TEXT" page="65" object_id="1167201962868958417" object_number="598"/>
</node>
</node>
<node TEXT="Codebook development" ID="ID_1724243440" CREATED="1714586717789" MODIFIED="1714586723122">
<node TEXT="iterative process of *codebook development*: first identify themes generally and without pondering on interpretations or relationships (what does this text mean to me?); then we systematize the codes to identify them in the texts reliably (what specific instances of meaning exist in this text?), we read again using the more clearly defined codes; at the end we look for connections between themes and codes (are there patterns of relationship among meaning instances in this text?)" ID="ID_805277960" CREATED="1714584200171" MODIFIED="1714584200171" LINK="project://16AA1F3483D6GEWV5A1JJLVG6C22R89VFR4E/../../../articulos/pedagogy/Guest2012AppliedThematicAnalysis.pdf">
<attribute NAME="key" VALUE="Guest2012AppliedThematicAnalysis"/>
<attribute NAME="title" VALUE="Applied Thematic Analysis"/>
<attribute NAME="authors" VALUE="Guest, Greg and MacQueen, Kathleen and Namey, Emily"/>
<pdf_annotation type="HIGHLIGHTED_TEXT" page="62" object_id="2655416296004057310" object_number="591"/>
</node>
<node TEXT="information that needs to be included in a code definition: label (brief mnemonic tag), short definition (short descriptive phrase that captures the essence of the theme), full definition (short paragraph highlighting key fetures of the theme, possibly including theoretical, conceptual or cultural dimensions), when to use (textual cues and context that signify thematic meaning), when not to use (textual cues and context that are more appropriate to other codes but could possibly overlap or be confused)" ID="ID_1913874981" CREATED="1714584199921" MODIFIED="1714584199921" LINK="project://16AA1F3483D6GEWV5A1JJLVG6C22R89VFR4E/../../../articulos/pedagogy/Guest2012AppliedThematicAnalysis.pdf">
<attribute NAME="key" VALUE="Guest2012AppliedThematicAnalysis"/>
<attribute NAME="title" VALUE="Applied Thematic Analysis"/>
<attribute NAME="authors" VALUE="Guest, Greg and MacQueen, Kathleen and Namey, Emily"/>
<pdf_annotation type="HIGHLIGHTED_TEXT" page="63" object_id="4431065465717149698" object_number="595"/>
</node>
<node TEXT="steps to *identify themes*: refresh your awareness and understanding of the analytic objectives to determine which themes to pay attention to (tag, define, code). Reread the data with that in mind and pay attention to linguistic cues: repetition, indigenous typologies, metaphors and analogies, transitions, comparing sections to note similarities and differences, discursive connectors, silence or missing data." ID="ID_1023994461" CREATED="1714584199497" MODIFIED="1714584199497" LINK="project://16AA1F3483D6GEWV5A1JJLVG6C22R89VFR4E/../../../articulos/pedagogy/Guest2012AppliedThematicAnalysis.pdf">
<attribute NAME="key" VALUE="Guest2012AppliedThematicAnalysis"/>
<attribute NAME="title" VALUE="Applied Thematic Analysis"/>
<attribute NAME="authors" VALUE="Guest, Greg and MacQueen, Kathleen and Namey, Emily"/>
<pdf_annotation type="HIGHLIGHTED_TEXT" page="78" object_id="445014661745446258" object_number="604"/>
</node>
</node>
<node TEXT="Quantitive elements and supporting techniques" ID="ID_1771837357" CREATED="1714586677059" MODIFIED="1714586690910">
<node TEXT="quantitave word-based analyses: word counts, semantic network analysis. Frequency and co-occurrence of words or phrases in a corpus to identify key words or ideas. Possibility for software-based analysis (see university resources)" ID="ID_1192959475" CREATED="1714584199574" MODIFIED="1714584199574" LINK="project://16AA1F3483D6GEWV5A1JJLVG6C22R89VFR4E/../../../articulos/pedagogy/Guest2012AppliedThematicAnalysis.pdf">
