<pdf_annotation type="HIGHLIGHTED_TEXT" page="129" object_id="6246382058439507327" object_number="668"/>
</node>
<node TEXT="Sometimes polemic practice: &quot;reducing&quot; qualitative data to quantitative, one must be very deliberate in when, why, and what to quantify in a qualitative data set" ID="ID_1425343289" CREATED="1714584199558" MODIFIED="1714584199558" LINK="project://16AA1F3483D6GEWV5A1JJLVG6C22R89VFR4E/../../../articulos/pedagogy/Guest2012AppliedThematicAnalysis.pdf">
<attribute NAME="key" VALUE="Guest2012AppliedThematicAnalysis"/>
