<attribute NAME="title" VALUE="Applied Thematic Analysis"/>
<attribute NAME="authors" VALUE="Guest, Greg and MacQueen, Kathleen and Namey, Emily"/>
<pdf_annotation type="HIGHLIGHTED_TEXT" page="155" object_id="4000529601484417832" object_number="680"/>
</node>
<node TEXT="use of frequencies during analysis: once codes have been developed and tagged, run frequencies to identify codes at extreme ends: the very low use ones may have to be deleted or combined with a similar code; very frequent use ones could be too broad and deed to be narrowed" ID="ID_753406051" CREATED="1714584199706" MODIFIED="1714584199706" LINK="project://16AA1F3483D6GEWV5A1JJLVG6C22R89VFR4E/../../../articulos/pedagogy/Guest2012AppliedThematicAnalysis.pdf">
